sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {},
    isDatePast: function(strDate) {
        // Create GlideDateTime objects for the current date and the passed in date
        var rightnow = new GlideDateTime();
        var testdate = new GlideDateTime(strDate);

        // If the testdate is before rightnow, return true, else return false
        if (testdate.before(rightnow)) {
            return true;
        } else {
            return false;
        }
    },

    isDateToday: function(strDate1) {
        // Create GLideDateTime objects for the current date and the passed in date
        var rightnow = new GlideDateTime();
        var testdate = new GlideDateTime(strDate1);
		var today = rightnow.getLocalDate();
		var isToday = testdate.getLocalDate();

        // If the testdate is 'equals' rightnow, return true, else return false
		if (today.equals(isToday)) { // updated this line from (today.compareTo(isToday) == 0)
			return true;
		} else {
			return false;
		}
    },

    type: 'NeedItUtils'
};
